import{_ as a,o,c as i,a2 as l}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"5.4 交流接触器","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-4-jiao-liu-jie-chu-qi.md","filePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-4-jiao-liu-jie-chu-qi.md","lastUpdated":1793095197000}'),r={name:"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-4-jiao-liu-jie-chu-qi.md"};function e(n,t,s,d,h,g){return o(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="_5-4-交流接触器" tabindex="-1">5.4 交流接触器 <a class="header-anchor" href="#_5-4-交流接触器" aria-label="Permalink to &quot;5.4 交流接触器&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>接触器是电气控制的&quot;总开关&quot;——用一个小线圈的电流,控制大电流主电路的通断,还能实现<strong>远距离控制、频繁操作、自动控制</strong>。电动机的点动、自锁、正反转控制全靠它。这一节讲清它的结构和工作原理。</p><h2 id="一、接触器是干什么的" tabindex="-1">一、接触器是干什么的 <a class="header-anchor" href="#一、接触器是干什么的" aria-label="Permalink to &quot;一、接触器是干什么的&quot;">​</a></h2><p><strong>交流接触器</strong>:利用<strong>电磁铁原理</strong>,用<strong>小电流控制大电流</strong>的自动电器。</p><ul><li>线圈电流小(控制回路),主电路电流大(主回路);</li><li>可以实现:按钮远距离控制、自动/顺序控制、频繁启停电动机。</li></ul><h2 id="二、结构组成" tabindex="-1">二、结构组成 <a class="header-anchor" href="#二、结构组成" aria-label="Permalink to &quot;二、结构组成&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>控制回路(小电流)             主回路(大电流)</span></span>
<span class="line"><span>  线圈 ──► 电磁铁吸合 ──► 主触头闭合 ──► 电动机通电</span></span></code></pre></div><p>主要部件:</p><table tabindex="0"><thead><tr><th>部件</th><th>作用</th></tr></thead><tbody><tr><td><strong>电磁系统</strong></td><td>线圈、铁芯、衔铁——线圈通电产生磁力吸合衔铁</td></tr><tr><td><strong>触头系统</strong></td><td>主触头(通断主电路,容量大)+ 辅助触头(用于控制回路)</td></tr><tr><td><strong>灭弧系统</strong></td><td>熄灭主触头分断时的电弧</td></tr><tr><td><strong>复位弹簧</strong></td><td>线圈断电后,弹簧把衔铁弹回,触头断开</td></tr></tbody></table><p><strong>触头的两种状态(必背)</strong>:</p><ul><li><strong>常开触头(NO)</strong>:线圈不通电时断开,通电后闭合;</li><li><strong>常闭触头(NC)</strong>:线圈不通电时闭合,通电后断开。</li></ul><blockquote><p>⚠️ 判断题高频:&quot;常开触头&quot;在线圈不通电时是断开的;&quot;常闭触头&quot;不通电时是闭合的。注意&quot;常开/常闭&quot;指的是<strong>断电状态</strong>。</p></blockquote><h2 id="三、工作原理" tabindex="-1">三、工作原理 <a class="header-anchor" href="#三、工作原理" aria-label="Permalink to &quot;三、工作原理&quot;">​</a></h2><ol><li><strong>吸合</strong>:线圈通电 → 铁芯产生磁力 → 吸合衔铁 → 主触头闭合 → 主电路接通;</li><li><strong>保持</strong>:线圈持续通电,触头保持闭合;</li><li><strong>释放</strong>:线圈断电 → 磁力消失 → 弹簧复位 → 主触头断开 → 主电路断电。</li></ol><blockquote><p>💡 <strong>水流类比</strong>:线圈是&quot;阀门开关&quot;,主触头是&quot;主管道阀门&quot;。用小开关控制线圈,就能间接控制大阀门——这就是&quot;小电流控制大电流&quot;。</p></blockquote><h2 id="四、主要参数与型号" tabindex="-1">四、主要参数与型号 <a class="header-anchor" href="#四、主要参数与型号" aria-label="Permalink to &quot;四、主要参数与型号&quot;">​</a></h2><ul><li><strong>额定电压</strong>:触头能承受的电压(如 380 V);</li><li><strong>额定电流</strong>:主触头能长期通过的电流;</li><li><strong>线圈电压</strong>:线圈额定工作电压(常见 36 V、110 V、220 V、380 V);</li><li><strong>操作频率</strong>:每小时允许的操作次数。</li></ul><p><strong>型号</strong>:CJ 系列(CJX2、CJ20 等),C 表示接触器,J 表示交流。</p><h2 id="五、选用要点" tabindex="-1">五、选用要点 <a class="header-anchor" href="#五、选用要点" aria-label="Permalink to &quot;五、选用要点&quot;">​</a></h2><ol><li>接触器额定电压、额定电流 ≥ 主电路要求;</li><li>线圈电压与<strong>控制回路电源</strong>一致;</li><li>按操作频率选型(频繁操作选允许频率高的)。</li></ol><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 接触器靠电磁原理,<strong>小电流控制大电流</strong>。</li><li>✅ 常开(NO)断电断开、通电闭合;常闭(NC)断电闭合、通电断开。</li><li>✅ 线圈断电 → 弹簧复位 → 触头断开,主电路断电。</li><li>⚠️ 易混点:常开/常闭的&quot;常&quot;指断电状态,别按通电状态记。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>交流接触器 = 电磁铁 + 触头,实现远距离、自动控制。</li><li>主触头通断主电路,辅助触头用于控制回路。</li><li>常开常闭触头按&quot;断电状态&quot;定义。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)交流接触器是利用电磁原理实现小电流控制大电流的电器。( )</li><li>(单选)常开触头在线圈不通电时处于()状态。 A. 闭合　B. 断开　C. 时通时断　D. 不确定</li><li>(判断)接触器线圈断电后,依靠复位弹簧使触头断开。( )</li><li>(单选)接触器的主触头用于通断()。 A. 控制回路　B. 主回路(主电路)　C. 信号回路　D. 接地回路</li><li>(判断)常闭触头在线圈通电时是闭合的。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。电磁原理,小电流控制大电流。</li><li><strong>B</strong>。常开(NO)= 断电断开,通电闭合。</li><li><strong>√</strong>。断电后弹簧复位断开触头。</li><li><strong>B</strong>。主触头通断主电路。</li><li><strong>×</strong>。常闭触头断电时闭合,通电时断开。</li></ol></details>`,28)])])}const q=a(r,[["render",e]]);export{c as __pageData,q as default};
